run:
() => {
      const K = window.KervanCore, out = [];
      for (let seed = 1; seed <= 12; seed++) {
        const sim = new K.KervanSim(seed), bot = new K.KervanBot(sim, 'smart');
        for (let h = 0; h < K.END_DAY * 24 + 48 && sim.S.status === 'playing'; h++) { bot.tick(); sim.advance(1); }
        const sc = sim.score();
        out.push({ status: sim.S.status, day: sc.day, stars: sc.stars, score: sc.score, hans: sim.ownedHans() });
      }
      window.__gateOut = out;
    }
